structs.TwoBitHeader:
typedef struct
{
    uint32_t magic;
    uint32_t version;
    uint32_t nChroms;
} TwoBitHeader;

structs.TwoBitMaskedIdx:
typedef struct
{
    uint32_t *size;
    uint32_t *nBlockCount;
    uint32_t **nBlockStart;
    uint32_t **nBlockSizes;
    uint32_t *maskBlockCount;
    uint32_t **maskBlockStart;
    uint32_t **maskBlockSizes;
    uint64_t *offset;
} TwoBitMaskedIdx;

structs.TwoBit:
typedef struct
{
    FILE *fp;
    uint64_t sz;
    uint64_t offset;
    void *data;
    TwoBitHeader *hdr;
    TwoBitCL *cl;
    TwoBitMaskedIdx *idx;
} TwoBit;

functions.twobitRead:
size_t twobitRead(void *data, size_t sz, size_t nmemb, TwoBit *tb)
{
    if (tb->data)
    {
        if (memcpy(data, tb->data + tb->offset, nmemb * sz) == ((void *)0))
            return 0;
        tb->offset += nmemb * sz;
        return nmemb;
    }
    else
    {
        return fread(data, sz, nmemb, tb->fp);
    }
}

functions.twobitSeek:
int twobitSeek(TwoBit *tb, uint64_t offset)
{
    if (offset >= tb->sz)
        return -1;
    if (tb->data)
    {
        tb->offset = offset;
        return 0;
    }
    else
    {
        return fseek(tb->fp, (long)offset, 0);
    }
}

functions.twobitTell:
uint64_t twobitTell(TwoBit *tb)
{
    if (tb->data)
        return tb->offset;
    return (uint64_t)ftell(tb->fp);
}

functions.byte2base:
char byte2base(uint8_t byte, int offset)
{
    int rev = 3 - offset;
    uint8_t mask = 3 << (2 * rev);
    int foo = (mask & byte) >> (2 * rev);
    char bases[4] = "TCAG";
    return bases[foo];
}

functions.bytes2bases:
void bytes2bases(char *seq, uint8_t *byte, uint32_t sz, int offset)
{
    uint32_t pos = 0, remainder = 0, i = 0;
    char bases[4] = "TCAG";
    uint8_t foo = byte[0];
    if (offset != 0)
    {
        while (offset < 4 && pos < sz)
        {
            seq[pos++] = byte2base(foo, offset++);
        }
        if (pos >= sz)
            return;
        foo = byte[++i];
    }
    remainder = (sz - pos) % 4;
    while (pos < sz - remainder)
    {
        foo = byte[i++];
        seq[pos + 3] = bases[foo & 3];
        foo >>= 2;
        seq[pos + 2] = bases[foo & 3];
        foo >>= 2;
        seq[pos + 1] = bases[foo & 3];
        foo >>= 2;
        seq[pos] = bases[foo & 3];
        foo >>= 2;
        pos += 4;
    }
    if (remainder > 0)
        foo = byte[i];
    for (offset = 0; offset < remainder; offset++)
    {
        seq[pos++] = byte2base(foo, offset);
    }
}

functions.NMask:
void NMask(char *seq, TwoBit *tb, uint32_t tid, uint32_t start, uint32_t end)
{
    uint32_t i, width, pos = 0;
    uint32_t blockStart, blockEnd;
    for (i = 0; i < tb->idx->nBlockCount[tid]; i++)
    {
        blockStart = tb->idx->nBlockStart[tid][i];
        blockEnd = blockStart + tb->idx->nBlockSizes[tid][i];
        if (blockEnd <= start)
            continue;
        if (blockStart >= end)
            break;
        if (blockStart < start)
        {
            blockEnd = (blockEnd < end) ? blockEnd : end;
            pos = 0;
            width = blockEnd - start;
        }
        else
        {
            blockEnd = (blockEnd < end) ? blockEnd : end;
            pos = blockStart - start;
            width = blockEnd - blockStart;
        }
        width += pos;
        for (; pos < width; pos++)
            seq[pos] = 'N';
    }
}

functions.softMask:
void softMask(char *seq, TwoBit *tb, uint32_t tid, uint32_t start, uint32_t end)
{
    uint32_t i, width, pos = 0;
    uint32_t blockStart, blockEnd;
    if (!tb->idx->maskBlockStart)
        return;
    for (i = 0; i < tb->idx->maskBlockCount[tid]; i++)
    {
        blockStart = tb->idx->maskBlockStart[tid][i];
        blockEnd = blockStart + tb->idx->maskBlockSizes[tid][i];
        if (blockEnd <= start)
            continue;
        if (blockStart >= end)
            break;
        if (blockStart < start)
        {
            blockEnd = (blockEnd < end) ? blockEnd : end;
            pos = 0;
            width = blockEnd - start;
        }
        else
        {
            blockEnd = (blockEnd < end) ? blockEnd : end;
            pos = blockStart - start;
            width = blockEnd - blockStart;
        }
        width += pos;
        for (; pos < width; pos++)
        {
            if (seq[pos] != 'N')
                seq[pos] = (__extension__({
                    int __res;
                    if (sizeof(seq[pos]) > 1)
                    {
                        if (__builtin_constant_p(seq[pos]))
                        {
                            int __c = (seq[pos]);
                            __res = __c < -128 || __c > 255 ? __c : (*__ctype_tolower_loc())[__c];
                        }
                        else
                            __res = tolower(seq[pos]);
                    }
                    else
                        __res = (*__ctype_tolower_loc())[(int)(seq[pos])];
                    __res;
                }));
        }
    }
}

functions.constructSequence:
char *constructSequence(TwoBit *tb, uint32_t tid, uint32_t start, uint32_t end)
{
    uint32_t sz = end - start + 1;
    uint32_t blockStart, blockEnd;
    char *seq = malloc(sz * sizeof(char));
    uint8_t *bytes = ((void *)0);
    int offset;
    if (!seq)
        return ((void *)0);
    blockStart = start / 4;
    offset = start % 4;
    blockEnd = end / 4 + ((end % 4) ? 1 : 0);
    bytes = malloc(blockEnd - blockStart);
    if (!bytes)
        goto error;
    if (twobitSeek(tb, tb->idx->offset[tid] + blockStart) != 0)
        goto error;
    if (twobitRead(bytes, blockEnd - blockStart, 1, tb) != 1)
        goto error;
    bytes2bases(seq, bytes, sz - 1, offset);
    free(bytes);
    seq[sz - 1] = '\0';
    NMask(seq, tb, tid, start, end);
    softMask(seq, tb, tid, start, end);
    return seq;
error:
    if (seq)
        free(seq);
    if (bytes)
        free(bytes);
    return ((void *)0);
}

functions.twobitSequence:
char *twobitSequence(TwoBit *tb, char *chrom, uint32_t start, uint32_t end)
{
    uint32_t i, tid = 0;
    for (i = 0; i < tb->hdr->nChroms; i++)
    {
        if (strcmp(tb->cl->chrom[i], chrom) == 0)
        {
            tid = i;
            break;
        }
    }
    if (tid == 0 && strcmp(tb->cl->chrom[i], chrom) != 0)
        return ((void *)0);
    if (start == end && end == 0)
    {
        end = tb->idx->size[tid];
    }
    if (end > tb->idx->size[tid])
        return ((void *)0);
    if (start >= end)
        return ((void *)0);
    return constructSequence(tb, tid, start, end);
}

functions.getMask:
void getMask(TwoBit *tb, uint32_t tid, uint32_t start, uint32_t end, uint32_t *maskIdx, uint32_t *maskStart,
             uint32_t *maskEnd)
{
    if (*maskIdx == (uint32_t)-1)
    {
        for ((*maskIdx) = 0; (*maskIdx) < tb->idx->nBlockCount[tid]; (*maskIdx)++)
        {
            *maskStart = tb->idx->nBlockStart[tid][*maskIdx];
            *maskEnd = (*maskStart) + tb->idx->nBlockSizes[tid][*maskIdx];
            if (*maskEnd < start)
                continue;
            if (*maskEnd >= start)
                break;
        }
    }
    else if (*maskIdx >= tb->idx->nBlockCount[tid])
    {
        *maskStart = (uint32_t)-1;
        *maskEnd = (uint32_t)-1;
    }
    else
    {
        *maskIdx += 1;
        if (*maskIdx >= tb->idx->nBlockCount[tid])
        {
            *maskStart = (uint32_t)-1;
            *maskEnd = (uint32_t)-1;
        }
        else
        {
            *maskStart = tb->idx->nBlockStart[tid][*maskIdx];
            *maskEnd = (*maskStart) + tb->idx->nBlockSizes[tid][*maskIdx];
        }
    }
    if (*maskIdx >= tb->idx->nBlockCount[tid] || *maskStart >= end)
    {
        *maskStart = (uint32_t)-1;
        *maskEnd = (uint32_t)-1;
    }
}

functions.getByteMaskFromOffset:
uint8_t getByteMaskFromOffset(int offset)
{
    switch (offset)
    {
    case 0:
        return (uint8_t)15;
    case 1:
        return (uint8_t)7;
    case 2:
        return (uint8_t)3;
    }
    return 1;
}

functions.twobitBasesWorker:
void *twobitBasesWorker(TwoBit *tb, uint32_t tid, uint32_t start, uint32_t end, int fraction)
{
    void *out;
    uint32_t tmp[4] = {0, 0, 0, 0}, len = end - start + (start % 4), i = 0, j = 0;
    uint32_t seqLen = end - start;
    uint32_t blockStart, blockEnd, maskIdx = (uint32_t)-1, maskStart, maskEnd, foo;
    uint8_t *bytes = ((void *)0), mask = 0, offset;
    if (fraction)
    {
        out = malloc(4 * sizeof(double));
    }
    else
    {
        out = malloc(4 * sizeof(uint32_t));
    }
    if (!out)
        return ((void *)0);
    blockStart = start / 4;
    offset = start % 4;
    blockEnd = end / 4 + ((end % 4) ? 1 : 0);
    bytes = malloc(blockEnd - blockStart);
    if (!bytes)
        goto error;
    mask = getByteMaskFromOffset(offset);
    start = 4 * blockStart;
    offset = 0;
    if (twobitSeek(tb, tb->idx->offset[tid] + blockStart) != 0)
        goto error;
    if (twobitRead(bytes, blockEnd - blockStart, 1, tb) != 1)
        goto error;
    getMask(tb, tid, start, end, &maskIdx, &maskStart, &maskEnd);
    while (i < len)
    {
        if (maskIdx != -1 && start + i + 4 >= maskStart)
        {
            if (start + i >= maskStart || start + i + 4 - offset > maskStart)
            {
                if (start + i >= maskStart && start + i + 4 - offset < maskEnd)
                {
                    i = maskEnd - start;
                    getMask(tb, tid, i, end, &maskIdx, &maskStart, &maskEnd);
                    offset = (start + i) % 4;
                    j = i / 4;
                    mask = getByteMaskFromOffset(offset);
                    i = 4 * j;
                    offset = 0;
                    continue;
                }
                foo = 4 * j + 4 * blockStart;
                if (mask & 1 && (foo + 3 >= maskStart && foo + 3 < maskEnd))
                    mask -= 1;
                if (mask & 2 && (foo + 2 >= maskStart && foo + 2 < maskEnd))
                    mask -= 2;
                if (mask & 4 && (foo + 1 >= maskStart && foo + 1 < maskEnd))
                    mask -= 4;
                if (mask & 8 && (foo >= maskStart && foo < maskEnd))
                    mask -= 8;
                if (foo + 4 > maskEnd)
                {
                    getMask(tb, tid, i, end, &maskIdx, &maskStart, &maskEnd);
                    continue;
                }
            }
        }
        if (i + 4 >= len)
        {
            if ((mask & 1) && i + 3 >= len)
                mask -= 1;
            if ((mask & 2) && i + 2 >= len)
                mask -= 2;
            if ((mask & 4) && i + 1 >= len)
                mask -= 4;
            if ((mask & 8) && i >= len)
                mask -= 8;
        }
        foo = bytes[j++];
        if (mask & 1)
        {
            tmp[foo & 3]++;
        }
        foo >>= 2;
        mask >>= 1;
        if (mask & 1)
        {
            tmp[foo & 3]++;
        }
        foo >>= 2;
        mask >>= 1;
        if (mask & 1)
        {
            tmp[foo & 3]++;
        }
        foo >>= 2;
        mask >>= 1;
        if (mask & 1)
        {
            tmp[foo & 3]++;
        }
        i += 4;
        mask = 15;
    }
    free(bytes);
    if (fraction)
    {
        ((double *)out)[0] = ((double)tmp[2]) / ((double)seqLen);
        ((double *)out)[1] = ((double)tmp[1]) / ((double)seqLen);
        ((double *)out)[2] = ((double)tmp[0]) / ((double)seqLen);
        ((double *)out)[3] = ((double)tmp[3]) / ((double)seqLen);
    }
    else
    {
        ((uint32_t *)out)[0] = tmp[2];
        ((uint32_t *)out)[1] = tmp[1];
        ((uint32_t *)out)[2] = tmp[0];
        ((uint32_t *)out)[3] = tmp[3];
    }
    return out;
error:
    if (out)
        free(out);
    if (bytes)
        free(bytes);
    return ((void *)0);
}

