functions.twobitIndexRead:
void twobitIndexRead(TwoBit *tb, int storeMasked)
{
    uint32_t i, data[2];
    TwoBitMaskedIdx *idx = calloc(1, sizeof(TwoBitMaskedIdx));
    if (!idx)
        return;
    idx->size = malloc(tb->hdr->nChroms * sizeof(uint32_t));
    idx->nBlockCount = calloc(tb->hdr->nChroms, sizeof(uint32_t));
    idx->nBlockStart = calloc(tb->hdr->nChroms, sizeof(uint32_t *));
    idx->nBlockSizes = calloc(tb->hdr->nChroms, sizeof(uint32_t *));
    if (!idx->size)
        goto error;
    if (!idx->nBlockCount)
        goto error;
    if (!idx->nBlockStart)
        goto error;
    if (!idx->nBlockSizes)
        goto error;
    idx->maskBlockCount = calloc(tb->hdr->nChroms, sizeof(uint32_t));
    if (!idx->maskBlockCount)
        goto error;
    if (storeMasked)
    {
        idx->maskBlockStart = calloc(tb->hdr->nChroms, sizeof(uint32_t *));
        idx->maskBlockSizes = calloc(tb->hdr->nChroms, sizeof(uint32_t *));
        if (!idx->maskBlockStart)
            goto error;
        if (!idx->maskBlockSizes)
            goto error;
    }
    idx->offset = malloc(tb->hdr->nChroms * sizeof(uint64_t));
    if (!idx->offset)
        goto error;
    for (i = 0; i < tb->hdr->nChroms; i++)
    {
        if (twobitSeek(tb, tb->cl->offset[i]) != 0)
            goto error;
        if (twobitRead(data, sizeof(uint32_t), 2, tb) != 2)
            goto error;
        idx->size[i] = data[0];
        idx->nBlockCount[i] = data[1];
        idx->nBlockStart[i] = malloc(idx->nBlockCount[i] * sizeof(uint32_t));
        idx->nBlockSizes[i] = malloc(idx->nBlockCount[i] * sizeof(uint32_t));
        if (!idx->nBlockStart[i])
            goto error;
        if (!idx->nBlockSizes[i])
            goto error;
        if (twobitRead(idx->nBlockStart[i], sizeof(uint32_t), idx->nBlockCount[i], tb) != idx->nBlockCount[i])
            goto error;
        if (twobitRead(idx->nBlockSizes[i], sizeof(uint32_t), idx->nBlockCount[i], tb) != idx->nBlockCount[i])
            goto error;
        if (twobitRead(idx->maskBlockCount + i, sizeof(uint32_t), 1, tb) != 1)
            goto error;
        if (storeMasked)
        {
            idx->maskBlockStart[i] = malloc(idx->maskBlockCount[i] * sizeof(uint32_t));
            idx->maskBlockSizes[i] = malloc(idx->maskBlockCount[i] * sizeof(uint32_t));
            if (!idx->maskBlockStart[i])
                goto error;
            if (!idx->maskBlockSizes[i])
                goto error;
            if (twobitRead(idx->maskBlockStart[i], sizeof(uint32_t), idx->maskBlockCount[i], tb) !=
                idx->maskBlockCount[i])
                goto error;
            if (twobitRead(idx->maskBlockSizes[i], sizeof(uint32_t), idx->maskBlockCount[i], tb) !=
                idx->maskBlockCount[i])
                goto error;
        }
        else
        {
            if (twobitSeek(tb, twobitTell(tb) + 8 * idx->maskBlockCount[i]) != 0)
                goto error;
        }
        if (twobitRead(data, sizeof(uint32_t), 1, tb) != 1)
            goto error;
        idx->offset[i] = twobitTell(tb);
    }
    tb->idx = idx;
    return;
error:
    if (idx)
    {
        if (idx->size)
            free(idx->size);
        if (idx->nBlockCount)
            free(idx->nBlockCount);
        if (idx->nBlockStart)
        {
            for (i = 0; i < tb->hdr->nChroms; i++)
            {
                if (idx->nBlockStart[i])
                    free(idx->nBlockStart[i]);
            }
            free(idx->nBlockStart[i]);
        }
        if (idx->nBlockSizes)
        {
            for (i = 0; i < tb->hdr->nChroms; i++)
            {
                if (idx->nBlockSizes[i])
                    free(idx->nBlockSizes[i]);
            }
            free(idx->nBlockSizes[i]);
        }
        if (idx->maskBlockCount)
            free(idx->maskBlockCount);
        if (idx->maskBlockStart)
        {
            for (i = 0; i < tb->hdr->nChroms; i++)
            {
                if (idx->maskBlockStart[i])
                    free(idx->maskBlockStart[i]);
            }
            free(idx->maskBlockStart[i]);
        }
        if (idx->maskBlockSizes)
        {
            for (i = 0; i < tb->hdr->nChroms; i++)
            {
                if (idx->maskBlockSizes[i])
                    free(idx->maskBlockSizes[i]);
            }
            free(idx->maskBlockSizes[i]);
        }
        if (idx->offset)
            free(idx->offset);
        free(idx);
    }
}

