functions.twobitChromListRead:
void twobitChromListRead(TwoBit *tb)
{
    uint32_t i;
    uint8_t byte;
    char *str = ((void *)0);
    TwoBitCL *cl = calloc(1, sizeof(TwoBitCL));
    if (!cl)
        goto error;
    cl->chrom = calloc(tb->hdr->nChroms, sizeof(char *));
    cl->offset = malloc(sizeof(uint32_t) * tb->hdr->nChroms);
    if (!cl->chrom)
        goto error;
    if (!cl->offset)
        goto error;
    for (i = 0; i < tb->hdr->nChroms; i++)
    {
        if (twobitRead(&byte, 1, 1, tb) != 1)
            goto error;
        str = calloc(1 + byte, sizeof(char));
        if (!str)
            goto error;
        if (twobitRead(str, 1, byte, tb) != byte)
            goto error;
        cl->chrom[i] = str;
        str = ((void *)0);
        if (twobitRead(cl->offset + i, sizeof(uint32_t), 1, tb) != 1)
            goto error;
    }
    tb->cl = cl;
    return;
error:
    if (str)
        free(str);
    if (cl)
    {
        if (cl->offset)
            free(cl->offset);
        if (cl->chrom)
        {
            for (i = 0; i < tb->hdr->nChroms; i++)
            {
                if (cl->chrom[i])
                    free(cl->chrom[i]);
            }
            free(cl->chrom);
        }
        free(cl);
    }
}

