functions.twobitHdrRead:
void twobitHdrRead(TwoBit *tb)
{
    uint32_t data[4];
    TwoBitHeader *hdr = calloc(1, sizeof(TwoBitHeader));
    if (!hdr)
        return;
    if (twobitRead(data, 4, 4, tb) != 4)
        goto error;
    hdr->magic = data[0];
    if (hdr->magic != 0x1A412743)
    {
        fprintf(stderr,
                "[twobitHdrRead] Received an invalid file magic number (0x%"
                "x"
                ")!\n",
                hdr->magic);
        goto error;
    }
    hdr->version = data[1];
    if (hdr->version != 0)
    {
        fprintf(stderr,
                "[twobitHdrRead] The file version is %"
                "u"
                " while only version 0 is defined!\n",
                hdr->version);
        goto error;
    }
    hdr->nChroms = data[2];
    if (hdr->nChroms == 0)
    {
        fprintf(stderr, "[twobitHdrRead] There are apparently no chromosomes/contigs in this file!\n");
        goto error;
    }
    tb->hdr = hdr;
    return;
error:
    if (hdr)
        free(hdr);
}

functions.twobitClose:
void twobitClose(TwoBit *tb)
{
