    {
        if (tb->fp)
            fclose(tb->fp);
        if (tb->data)
            munmap(tb->data, tb->sz);
        twobitChromListDestroy(tb);
        twobitIndexDestroy(tb);
        twobitHdrDestroy(tb);
        free(tb);
    }
}

